//! Which files of the archive 100 hold the cry of a species and of a form: for each row, the first row of its forms and the voice of the
//! four kinds of cries. A voice is the number of the file of the wave archive in the high 16 bits and the number of the file of the
//! sequence in the low 16 bits. Generated from the data of the game: do not edit by hand.

/// The species of the game.
pub const SPECIES: usize = 721;

/// The kinds of cries, in the order of the columns.
pub const KINDS: [&str; 4] = ["Normal", "Battle", "Faint", "Special"];

/// The files of a cry: the sequence and the wave archive, as numbers of files of the archive of the cries.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Voice {
    pub sequence: u32,
    pub wave: u32,
}

/// The files of the cry of a species and a form, for a kind of cry (an index of [`KINDS`]). None when the game has no cry for it.
pub fn voice(species: usize, form: usize, kind: usize) -> Option<Voice> {
    // The rows after the 721 species are the forms of the species that have their own cry.
    if kind >= KINDS.len() || species > SPECIES {
        return None;
    }
    // A form that has its own cry has its row after the rows of the species.
    let first_form_row = ROWS.get(species)?[0] as usize;
    let row = if form > 0 && first_form_row != 0 { first_form_row + form - 1 } else { species };
    let id = ROWS.get(row)?[1 + kind];
    (id != 0).then_some(Voice { sequence: id & 0xFFFF, wave: id >> 16 })
}

