#[cfg(test)]
mod test {
    use super::*;

    #[test]
    fn a_species_and_its_forms_have_their_files() {
        assert_eq!(voice(1, 0, 0), Some(Voice { sequence: 0, wave: 3776 }));
        // Venusaur: the Mega Evolution is the form 1 of the cry table.
        assert_eq!(voice(3, 0, 0).unwrap().wave, 0xec2);
        assert_ne!(voice(3, 1, 0), voice(3, 0, 0));
        // A form without a cry of its own uses the cry of the species.
        assert_eq!(voice(1, 3, 0), voice(1, 0, 0));
        assert_eq!(voice(0, 0, 0), None);
        assert_eq!(voice(1, 0, 9), None);
        // A species of a pack is not in the table: the rows after the 721 species belong to the forms.
        assert_eq!(voice(724, 0, 0), None);
    }
}
